class TieredPricingStrategy {
  private readonly TAX_RATE = 0.08;
  private readonly PROCESSING_FEE = 0.029;

  calculateTotal(basePrice: number): number {
    const tax = basePrice * this.TAX_RATE;
    const fee = basePrice * this.PROCESSING_FEE;
    return basePrice + tax + fee;
  }
}

